const express = require('express');
const { Queue } = require('bullmq');
const { jwtAuth } = require('../middleware/auth');
const Channel = require('../models/Channel');
const UploadTracker = require('../models/UploadTracker');

const router = express.Router();
const transcodeQueue = new Queue('video-transcode');

router.post('/api/tus/videos/:uploadId/complete', jwtAuth, async (req, res) => {
  const { uploadId } = req.params;
  const { targetChannelId, resolution } = req.body;

  const [channel, upload] = await Promise.all([
    Channel.findOne({ _id: targetChannelId, ownerId: req.user.id }),
    UploadTracker.findOne({ uploadId, userId: req.user.id }),
  ]);

  if (!channel || !upload) {
    return res.status(403).json({ error: 'Access denied: channel or upload does not belong to you' });
  }

  await transcodeQueue.add('process_video', {
    uploadId,
    channelId: targetChannelId,
    res: resolution || '1080p',
  });

  res.json({ success: true, message: 'Video queued for publishing' });
});
